// Extract event info, prune heavy diff payloads, and parse task key
const body = $json.body || $json;
const headers = $json.headers || {};

const action = body.action || 'push';
const pr = body.pull_request || {};
const isMerged = Boolean(pr.merged);
const title = pr.title || body.head_commit?.message || '';
const branch = pr.head?.ref || body.ref || '';
const prUrl = pr.html_url || '';

// Match task key pattern (e.g. IDP-035, GITOPS-003, AREA-123)
const match = (title + ' ' + branch).toUpperCase().match(/\b([A-Z]{2,10}-\d+)\b/);
const taskKey = match ? match[1] : null;

let targetBucket = 'In Progress';
if (action === 'closed' && isMerged) {
  targetBucket = 'Done';
} else if (['opened', 'synchronize', 'reopened'].includes(action)) {
  targetBucket = 'In Review';
}

return [{
  json: {
    taskKey: taskKey,
    action: action,
    isMerged: isMerged,
    targetBucket: targetBucket,
    prUrl: prUrl,
    title: title,
    hasTask: Boolean(taskKey)
  }
}];
